"""Random Forest flow classifier trained on SYNTHETIC data, for live flows.

IMPORTANT - read before relying on it:
* The training data is generated by hand-written statistical profiles (see PROFILES). It is
  not real attack traffic. The model learns those profiles, so its hold-out scores measure
  "can it recover the synthetic generator", NOT real-world detection accuracy.
* It uses only features the live flow aggregator genuinely computes (no UNSW-NB15 fields),
  so, unlike the Phase-4 UNSW model, it is schema-compatible with live flows. It is an
  experimental, demo-grade signal and complements the rule-based IDS; it is not proof of
  compromise.
"""
from __future__ import annotations

import json
import threading
import time
from collections import deque
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path

import joblib
import numpy as np
from sklearn.ensemble import RandomForestClassifier
from sklearn.metrics import accuracy_score, confusion_matrix, f1_score
from sklearn.model_selection import train_test_split

from app.security.flow_aggregator import CompletedFlow
from app.security.traffic_filters import is_noise_destination

FEATURES = ["dur", "spkts", "dpkts", "sbytes", "dbytes", "rate", "smean", "dmean",
            "is_tcp", "is_udp", "byte_ratio", "pkt_ratio"]
CLASSES = ["normal", "port_scan", "dos_flood", "data_exfiltration"]
MODEL_PATH = Path("models/live_synthetic_rf.joblib")
REPORT_PATH = Path("models/live_synthetic_report.json")
# An attack label below this confidence is treated as normal: the model is synthetic-trained and
# real traffic is often out of its depth, so weak guesses must not raise alerts.
MIN_ATTACK_CONFIDENCE = 0.80
SEVERITY = {"normal": "NORMAL", "port_scan": "SUSPICIOUS", "dos_flood": "SUSPICIOUS",
            "data_exfiltration": "SUSPICIOUS"}


def build_features(dur, spkts, dpkts, sbytes, dbytes, proto) -> list[float]:
    total_p = spkts + dpkts
    rate = total_p / dur if dur > 0 else 0.0
    smean = sbytes / spkts if spkts else 0.0
    dmean = dbytes / dpkts if dpkts else 0.0
    proto = (proto or "").lower()
    return [dur, spkts, dpkts, sbytes, dbytes, rate, smean, dmean,
            1.0 if proto == "tcp" else 0.0, 1.0 if proto == "udp" else 0.0,
            sbytes / (dbytes + 1.0), spkts / (dpkts + 1.0)]


def features_from_flow(flow: CompletedFlow) -> list[float]:
    return build_features(flow.duration, flow.source_packets, flow.destination_packets,
                          flow.source_bytes, flow.destination_bytes, flow.protocol)


# ---- synthetic generator (documented profiles) ----
def _normal(rng):
    kind = rng.choice(["web", "dns", "stream", "chat"], p=[.45, .2, .2, .15])
    if kind == "dns":
        return build_features(rng.uniform(.01, .3), 1, 1, rng.integers(60, 120), rng.integers(80, 300), "udp")
    if kind == "web":
        sp = int(rng.integers(5, 60)); dp = int(sp * rng.uniform(1, 4))
        return build_features(rng.uniform(.2, 20), sp, dp, sp * rng.integers(100, 600), dp * rng.integers(500, 1400), "tcp")
    if kind == "stream":
        dp = int(rng.integers(200, 3000)); sp = int(dp * rng.uniform(.03, .15))
        return build_features(rng.uniform(5, 120), sp, dp, sp * 60, dp * rng.integers(1000, 1450), "tcp")
    sp = int(rng.integers(10, 200)); dp = int(sp * rng.uniform(.6, 1.4))
    return build_features(rng.uniform(5, 300), sp, dp, sp * rng.integers(80, 300), dp * rng.integers(80, 300), rng.choice(["tcp", "udp"]))


def _scan(rng):
    sp = int(rng.integers(1, 4)); dp = int(rng.integers(0, 2))
    return build_features(rng.uniform(0, .05), sp, dp, sp * rng.integers(40, 70), dp * rng.integers(40, 70), "tcp")


def _flood(rng):
    sp = int(rng.integers(500, 20000))
    return build_features(rng.uniform(.5, 10), sp, int(rng.integers(0, 3)), sp * rng.integers(40, 120), int(rng.integers(0, 200)), rng.choice(["tcp", "udp"]))


def _exfil(rng):
    sp = int(rng.integers(500, 8000)); dp = int(sp * rng.uniform(.02, .1))
    return build_features(rng.uniform(20, 600), sp, dp, sp * rng.integers(1100, 1460), dp * rng.integers(40, 100), "tcp")


PROFILES = {"normal": _normal, "port_scan": _scan, "dos_flood": _flood, "data_exfiltration": _exfil}


def generate(n_per_class: int = 4000, seed: int = 42):
    rng = np.random.default_rng(seed)
    X, y = [], []
    for label, fn in PROFILES.items():
        weight = 2 if label == "normal" else 1
        for _ in range(n_per_class * weight):
            X.append(fn(rng))
            y.append(label)
    return np.array(X, dtype=float), np.array(y)


def train(model_path: Path = MODEL_PATH, report_path: Path = REPORT_PATH, seed: int = 42) -> dict:
    X, y = generate(seed=seed)
    Xtr, Xte, ytr, yte = train_test_split(X, y, test_size=0.25, stratify=y, random_state=seed)
    clf = RandomForestClassifier(n_estimators=80, max_depth=14, min_samples_leaf=3, n_jobs=-1, random_state=seed)
    t0 = time.perf_counter()
    clf.fit(Xtr, ytr)
    fit_s = time.perf_counter() - t0
    pred = clf.predict(Xte)
    # Stress test: multiplicative noise so the model is not scored only on clean profiles.
    rng = np.random.default_rng(seed + 1)
    noisy = Xte * rng.uniform(0.7, 1.3, Xte.shape)
    report = {
        "data": "SYNTHETIC (hand-written profiles); not real traffic",
        "classes": CLASSES, "features": FEATURES, "train_rows": len(Xtr), "test_rows": len(Xte),
        "holdout_accuracy": float(accuracy_score(yte, pred)),
        "holdout_macro_f1": float(f1_score(yte, pred, average="macro")),
        "noisy_holdout_accuracy": float(accuracy_score(yte, clf.predict(noisy))),
        "confusion_matrix": {"labels": CLASSES, "matrix": confusion_matrix(yte, pred, labels=CLASSES).tolist()},
        "train_seconds": round(fit_s, 2),
        "caveat": "Scores measure recovery of the synthetic generator, not real-world detection.",
    }
    Path(model_path).parent.mkdir(parents=True, exist_ok=True)
    joblib.dump({"model": clf, "features": FEATURES, "classes": list(clf.classes_)}, model_path, compress=3)
    Path(report_path).write_text(json.dumps(report, indent=2))
    return report


@dataclass(frozen=True)
class MLEvent:
    timestamp: str
    label: str
    severity: str
    probability: float
    source_ip: str
    destination_ip: str
    destination_port: int | None
    protocol: str


class LiveMLAnalyzer:
    """Scores completed live flows with the synthetic-trained Random Forest."""

    def __init__(self, model_path: Path = MODEL_PATH, max_events: int = 200, batch: bool = False,
                 max_pending: int = 5000) -> None:
        self.model_path = Path(model_path)
        self._lock = threading.Lock()
        self._model = None
        self._events: deque[MLEvent] = deque(maxlen=max_events)
        self.active = False
        self.flows_scored = 0
        self.attack_flows = 0
        self.error: str | None = None
        self.batch = batch
        self._pending: deque[CompletedFlow] = deque(maxlen=max_pending)
        self.dropped_flows = 0
        self.skipped_noise = 0

    @property
    def loaded(self) -> bool:
        return self._model is not None

    def load_or_train(self) -> str:
        """Load the saved model, or train a fresh one (a few seconds) if none/invalid. Returns a status."""
        try:
            bundle = joblib.load(self.model_path)
            if bundle["features"] != FEATURES:
                raise ValueError("feature schema mismatch")
            status = "loaded"
        except Exception:
            train(self.model_path, self.model_path.with_name("live_synthetic_report.json"))
            bundle = joblib.load(self.model_path)
            status = "trained"
        self._model = bundle["model"]
        self.error = None
        return status

    def start(self) -> None:
        if not self.loaded:
            raise RuntimeError("model not loaded")
        with self._lock:
            self.active = True

    def stop(self) -> None:
        with self._lock:
            self.active = False

    @property
    def events(self) -> tuple[MLEvent, ...]:
        with self._lock:
            return tuple(self._events)

    def predict_flow(self, flow: CompletedFlow) -> tuple[str, float]:
        x = np.array([features_from_flow(flow)])
        proba = self._model.predict_proba(x)[0]
        i = int(np.argmax(proba))
        return str(self._model.classes_[i]), float(proba[i])

    def inspect_completed_flow(self, flow: CompletedFlow) -> None:
        if not self.active or not self.loaded:
            return
        if is_noise_destination(flow.destination_ip):  # multicast / broadcast discovery chatter
            with self._lock:
                self.skipped_noise += 1
            return
        if self.batch:  # queue now, score many flows at once in flush() (much cheaper than one by one)
            with self._lock:
                if len(self._pending) == self._pending.maxlen:
                    self.dropped_flows += 1
                self._pending.append(flow)
            return
        self._score([flow])

    def flush(self) -> int:
        """Score all queued flows with one vectorised model call. Returns how many were scored."""
        with self._lock:
            flows = list(self._pending)
            self._pending.clear()
        if flows and self.active and self.loaded:
            self._score(flows)
        return len(flows)

    def _score(self, flows: list[CompletedFlow]) -> None:
        try:
            x = np.array([features_from_flow(f) for f in flows])
            proba = self._model.predict_proba(x)
            idx = proba.argmax(axis=1)
            labels = [str(self._model.classes_[i]) for i in idx]
            confs = proba[np.arange(len(flows)), idx]
            labels = [lab if (lab == "normal" or c >= MIN_ATTACK_CONFIDENCE) else "normal"
                      for lab, c in zip(labels, confs)]
        except Exception as exc:  # never break capture because of the analyzer
            self.error = str(exc)
            return
        stamp = datetime.now(timezone.utc).isoformat(timespec="seconds")
        with self._lock:
            for f, label, p in zip(flows, labels, confs):
                self.flows_scored += 1
                if label != "normal":
                    self.attack_flows += 1
                self._events.append(MLEvent(stamp, label, SEVERITY.get(label, "SUSPICIOUS"), float(p), f.source_ip,
                                            f.destination_ip, f.destination_port, f.protocol))


if __name__ == "__main__":
    r = train()
    print(json.dumps({k: r[k] for k in ("holdout_accuracy", "holdout_macro_f1", "noisy_holdout_accuracy", "train_seconds")}, indent=2))
    print(r["caveat"])
